//! Native account sessions. Passwords are sent only to the fixed HTTPS account
//! service and are never persisted. Remembered tokens stay in an AEAD-encrypted
//! device registry; the browser receives only public profile summaries.
use std::{collections::BTreeMap,path::{Path,PathBuf},sync::{atomic::{AtomicBool,Ordering},RwLock},time::Duration};
use anyhow::{Context,Result};
use base64::{Engine,engine::general_purpose::STANDARD};
use ring::aead;
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use tokio::sync::Mutex;

pub const SERVICE:&str="https://plazcode-accounts-stoveez.mistysong24.chatgpt.site";
pub static ACCESS:once_cell::sync::Lazy<tokio::sync::RwLock<()>>=once_cell::sync::Lazy::new(||tokio::sync::RwLock::new(()));
const AAD:&[u8]=b"PlazCode remembered profiles v1";
const MAX_REGISTRY:u64=1024*1024;
#[derive(Clone,Serialize,Deserialize)]
struct Saved {id:String,username:String,token:Option<String>,expires_at:u64,#[serde(default)]appearance:Value,#[serde(default)]ui_migrated:bool}
#[derive(Default,Serialize,Deserialize)]
struct Registry {#[serde(default)]profiles:BTreeMap<String,Saved>,#[serde(default)]first_profile:Option<String>}
#[derive(Serialize,Deserialize)]
struct Envelope {version:u32,nonce:String,ciphertext:String}
#[derive(Clone,Serialize)]
pub struct Active {pub id:String,pub username:String,pub epoch:String,pub offline:bool,pub migrate_ui:bool,pub owns_legacy_data:bool}
pub struct Candidate {saved:Saved,pub offline:bool}
#[derive(Debug)]
pub struct AccountError {pub status:u16,pub code:&'static str,pub message:String}
impl std::fmt::Display for AccountError{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{f.write_str(&self.message)}}
impl std::error::Error for AccountError{}
fn failure(status:u16,code:&'static str,message:&str)->anyhow::Error{AccountError{status,code,message:message.into()}.into()}
pub fn now()->u64{chrono::Utc::now().timestamp_millis().max(0) as u64}
fn random(size:usize)->Result<Vec<u8>>{let mut bytes=vec![0;size];getrandom::getrandom(&mut bytes).map_err(|e|anyhow::anyhow!("Could not prepare account security: {e}"))?;Ok(bytes)}
fn hex(bytes:&[u8])->String{bytes.iter().map(|b|format!("{b:02x}")).collect()}
fn unhex(text:&str)->Result<Vec<u8>>{anyhow::ensure!(text.len()%2==0&&text.bytes().all(|b|b.is_ascii_hexdigit()),"Invalid encrypted profile data");(0..text.len()).step_by(2).map(|i|u8::from_str_radix(&text[i..i+2],16).map_err(Into::into)).collect()}
fn private_dir(path:&Path)->Result<()>{if path.exists(){anyhow::ensure!(!std::fs::symlink_metadata(path)?.file_type().is_symlink(),"Account directory must not be a symlink");}if path.exists(){anyhow::ensure!(!std::fs::symlink_metadata(path)?.file_type().is_symlink(),"Profile directory must not be a symlink");}std::fs::create_dir_all(path)?;#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;std::fs::set_permissions(path,std::fs::Permissions::from_mode(0o700))?;}Ok(())}
fn write_private(path:&Path,bytes:&[u8])->Result<()>{use std::io::Write;let mut options=std::fs::OpenOptions::new();options.write(true).create_new(true);#[cfg(unix)]{use std::os::unix::fs::OpenOptionsExt;options.mode(0o600);}let mut file=options.open(path)?;file.write_all(bytes)?;file.sync_all()?;Ok(())}
fn device_key(root:&Path)->Result<[u8;32]>{private_dir(root)?;let path=root.join("accounts-local-key");if !path.exists(){let bytes=random(32)?;match write_private(&path,&bytes){Ok(())=>{},Err(e)if path.exists()=>{let _=e;},Err(e)=>return Err(e)}}anyhow::ensure!(!std::fs::symlink_metadata(&path)?.file_type().is_symlink(),"Saved account key must not be a symlink");let bytes=std::fs::read(path)?;bytes.try_into().map_err(|_|anyhow::anyhow!("Saved account key has the wrong size"))}
fn seal(registry:&Registry,key:&[u8;32])->Result<Vec<u8>>{let nonce:[u8;12]=random(12)?.try_into().unwrap();let mut bytes=serde_json::to_vec(registry)?;let key=aead::LessSafeKey::new(aead::UnboundKey::new(&aead::AES_256_GCM,key).map_err(|_|anyhow::anyhow!("Account encryption unavailable"))?);key.seal_in_place_append_tag(aead::Nonce::assume_unique_for_key(nonce),aead::Aad::from(AAD),&mut bytes).map_err(|_|anyhow::anyhow!("Could not encrypt saved profiles"))?;Ok(serde_json::to_vec(&Envelope{version:1,nonce:hex(&nonce),ciphertext:STANDARD.encode(bytes)})?)}
fn open(bytes:&[u8],key:&[u8;32])->Result<Registry>{anyhow::ensure!(bytes.len() as u64<=MAX_REGISTRY,"Saved profile file is too large");let envelope:Envelope=serde_json::from_slice(bytes)?;anyhow::ensure!(envelope.version==1,"Unsupported saved profile format");let nonce:[u8;12]=unhex(&envelope.nonce)?.try_into().map_err(|_|anyhow::anyhow!("Invalid saved profile nonce"))?;let mut bytes=STANDARD.decode(envelope.ciphertext)?;let key=aead::LessSafeKey::new(aead::UnboundKey::new(&aead::AES_256_GCM,key).map_err(|_|anyhow::anyhow!("Account decryption unavailable"))?);let clear=key.open_in_place(aead::Nonce::assume_unique_for_key(nonce),aead::Aad::from(AAD),&mut bytes).map_err(|_|anyhow::anyhow!("Saved sign-ins could not be unlocked"))?;let registry:Registry=serde_json::from_slice(clear)?;anyhow::ensure!(registry.profiles.len()<=50,"Too many saved profiles");for(id,p)in &registry.profiles{crate::profile_paths::profile_root(id)?;anyhow::ensure!(&p.id==id&&!p.username.is_empty()&&p.username.len()<=32,"Invalid saved profile");}Ok(registry)}
fn atomic_registry(path:&Path,registry:&Registry,key:&[u8;32])->Result<()>{let parent=path.parent().context("Missing profile registry directory")?;private_dir(parent)?;let temporary=parent.join(format!("accounts-{}.tmp",hex(&random(8)?)));let bytes=seal(registry,key)?;write_private(&temporary,&bytes)?;let backup=path.with_extension("backup");if path.exists(){anyhow::ensure!(!std::fs::symlink_metadata(path)?.file_type().is_symlink(),"Saved profiles must not be a symlink");if backup.exists(){std::fs::remove_file(&backup)?;}std::fs::rename(path,&backup)?;}if let Err(error)=std::fs::rename(&temporary,path){if backup.exists()&&!path.exists(){let _=std::fs::rename(&backup,path);}let _=std::fs::remove_file(&temporary);return Err(error.into());}Ok(())}
fn read_registry(path:&Path,key:&[u8;32])->Result<Registry>{let backup=path.with_extension("backup");let read=|file:&Path|->Result<Registry>{anyhow::ensure!(!std::fs::symlink_metadata(file)?.file_type().is_symlink(),"Saved profiles must not be a symlink");anyhow::ensure!(std::fs::metadata(file)?.len()<=MAX_REGISTRY,"Saved profile file is too large");open(&std::fs::read(file)?,key)};if path.exists(){match read(path){Ok(registry)=>return Ok(registry),Err(error)if !backup.exists()=>return Err(error),Err(_)=>{}}}if backup.exists(){return read(&backup);}Ok(Registry::default())}
fn appearance(path:&Path)->Value{std::fs::read(path.join("plazcode-settings.json")).ok().and_then(|bytes|serde_json::from_slice::<Value>(&bytes).ok()).and_then(|v|v.get("rsAppearance").cloned()).unwrap_or_else(||json!({"theme":"default","glow":"subtle","gradients":"on"}))}
fn copy_tree(source:&Path,target:&Path)->Result<()>{let metadata=std::fs::symlink_metadata(source)?;anyhow::ensure!(!metadata.file_type().is_symlink(),"Existing profile data contains a symbolic link; the original has been kept");if metadata.is_dir(){std::fs::create_dir_all(target)?;for entry in std::fs::read_dir(source)?{let entry=entry?;copy_tree(&entry.path(),&target.join(entry.file_name()))?;}}else if metadata.is_file(){std::fs::copy(source,target)?;}Ok(())}
fn migrate(root:&Path,first:bool)->Result<()>{migrate_from(root,first,&crate::profile_paths::legacy_data_root(),&crate::profile_paths::legacy_settings_path())}
fn migrate_from(root:&Path,first:bool,legacy:&Path,settings:&Path)->Result<()>{if root.exists(){anyhow::ensure!(!std::fs::symlink_metadata(root)?.file_type().is_symlink(),"Profile data must not be a symlink");}if root.join(".profile-ready").is_file(){return Ok(());}let parent=root.parent().context("Missing profile directory")?;private_dir(parent)?;if root.exists(){anyhow::ensure!(!std::fs::symlink_metadata(root)?.file_type().is_symlink(),"Profile data must not be a symlink");if !first {write_private(&root.join(".profile-ready"),b"1")?;return Ok(());}}
 let staging=parent.join(format!(".migrate-{}",hex(&random(8)?)));private_dir(&staging)?;
 let result=(||->Result<()>{if first{for name in ["memory.json","shared-learning.json","skills.json","skills.json.backup","vault-settings.json","checkpoints.json","chat-history.json","creations.json","toolkit","Vault","engram","templates"]{let source=legacy.join(name);if source.exists(){copy_tree(&source,&staging.join(name))?;}}if settings.is_file(){copy_tree(&settings,&staging.join("plazcode-settings.json"))?;}if let Some(folder)=settings.parent(){let config=folder.join("config.json");if config.is_file(){copy_tree(&config,&staging.join("config.json"))?;}}}write_private(&staging.join(".profile-ready"),b"1")?;if root.exists(){// Recovery may find data already created for this exact online identity. Never overwrite it.
 for entry in std::fs::read_dir(&staging)?{let entry=entry?;let target=root.join(entry.file_name());if !target.exists(){std::fs::rename(entry.path(),target)?;}}std::fs::remove_dir_all(&staging)?;
 }else{std::fs::rename(&staging,root)?;}Ok(())})();if result.is_err(){let _=std::fs::remove_dir_all(staging);}result}

pub struct Manager {
 root:PathBuf,file:PathBuf,key:[u8;32],registry:Mutex<Registry>,active:RwLock<Option<Active>>,required:AtomicBool,
 client:reqwest::Client,service:String,warning:RwLock<Option<String>>,
 #[cfg(debug_assertions)]service_access:Option<String>,
}
impl Manager {
 pub fn disabled()->Self{Self{root:PathBuf::new(),file:PathBuf::new(),key:[0;32],registry:Mutex::new(Registry::default()),active:RwLock::new(None),required:AtomicBool::new(false),client:reqwest::Client::new(),service:SERVICE.into(),warning:RwLock::new(None),#[cfg(debug_assertions)]service_access:None}}
 pub fn load(headless:bool)->Result<Self>{let root=crate::profile_paths::legacy_data_root();let file=root.join("accounts.v1.json");let key=device_key(&root)?;let (mut registry,warning)=match read_registry(&file,&key){Ok(registry)=>(registry,None),Err(_)=>(Registry::default(),Some("Saved sign-ins could not be read. Use your username and password to recover access; your profile data has been kept.".into()))};let owner=root.join("first-profile");if owner.is_file(){let id=std::fs::read_to_string(&owner)?;crate::profile_paths::profile_root(id.trim())?;registry.first_profile=Some(id.trim().into());}
 if registry.first_profile.is_none()&&std::fs::read_dir(root.join("profiles")).ok().is_some_and(|entries|entries.flatten().any(|entry|entry.file_name().to_str().is_some_and(|id|crate::profile_paths::profile_root(id).is_ok()))){registry.first_profile=Some("00000000-0000-0000-0000-000000000000".into());}
 let required=!headless||registry.first_profile.is_some()||file.exists()||file.with_extension("backup").exists()||owner.exists();crate::profile_paths::initialize(required);
 #[allow(unused_mut)]let mut service=SERVICE.to_string();
 #[cfg(debug_assertions)]if let Ok(value)=std::env::var("PLAZCODE_ACCOUNT_SERVICE"){let url=reqwest::Url::parse(&value)?;anyhow::ensure!(url.scheme()=="http"&&url.host_str().and_then(|h|h.parse::<std::net::IpAddr>().ok()).is_some_and(|ip|ip.is_loopback()),"Debug account service must use a loopback address");service=value.trim_end_matches('/').into();}
 #[cfg(debug_assertions)]let require_profile=std::env::var("PLAZCODE_REQUIRE_PROFILE").ok().as_deref()==Some("1");
 #[cfg(not(debug_assertions))]let require_profile=false;
 let required=required||require_profile;if required{crate::profile_paths::initialize(true);}
 let builder=reqwest::Client::builder().connect_timeout(Duration::from_secs(4)).timeout(Duration::from_secs(15)).redirect(reqwest::redirect::Policy::none()).user_agent("PlazCode-accounts/1");
 #[cfg(debug_assertions)]let builder=if let Ok(path)=std::env::var("NODE_EXTRA_CA_CERTS"){builder.add_root_certificate(reqwest::Certificate::from_pem(&std::fs::read(path)?)?)}else{builder};
 Ok(Self{root,file,key,registry:Mutex::new(registry),active:RwLock::new(None),required:AtomicBool::new(required),client:builder.build()?,service,warning:RwLock::new(warning),#[cfg(debug_assertions)]service_access:std::env::var("PLAZCODE_ACCOUNT_SERVICE_ACCESS").ok()})}
 pub fn begin_profile_mode(&self){self.required.store(true,Ordering::Release);}
 pub fn required(&self)->bool{self.required.load(Ordering::Acquire)}
 pub fn active(&self)->Option<Active>{self.active.read().unwrap_or_else(|e|e.into_inner()).clone()}
 pub fn lock(&self){*self.active.write().unwrap_or_else(|e|e.into_inner())=None;}
 pub async fn portal(&self)->Value{let registry=self.registry.lock().await;let profiles=registry.profiles.values().map(|p|json!({"id":p.id,"username":p.username,"appearance":crate::profile_paths::profile_root(&p.id).ok().filter(|root|root.join("plazcode-settings.json").is_file()).map(|root|appearance(&root)).unwrap_or_else(||p.appearance.clone()),"remembered":p.token.is_some()&&p.expires_at>now()})).collect::<Vec<_>>();json!({"enabled":self.required(),"profiles":profiles,"active":self.active(),"warning":self.warning.read().unwrap_or_else(|e|e.into_inner()).clone()})}
 async fn request(&self,method:reqwest::Method,path:&str,body:Option<Value>,token:Option<&str>)->Result<Value>{let mut request=self.client.request(method,format!("{}{path}",self.service));if let Some(body)=body{request=request.json(&body);}if let Some(token)=token{request=request.bearer_auth(token);}
 #[cfg(debug_assertions)]if self.service==SERVICE{if let Some(token)=&self.service_access{request=request.header("OAI-Sites-Authorization",format!("Bearer {token}"));}}
 let response=request.send().await.map_err(|_|failure(503,"offline","Could not reach the account service. Check your connection and try again."))?;let status=response.status();if status.is_server_error()||status.as_u16()==429{return Err(failure(503,"offline","The account service is temporarily unavailable. Try again in a moment."));}let mut stream=response.bytes_stream();let mut bytes=Vec::new();use futures::StreamExt;while let Some(chunk)=stream.next().await{let chunk=chunk.map_err(|_|failure(503,"offline","The account connection was interrupted. Please try again."))?;anyhow::ensure!(bytes.len()+chunk.len()<=2*1024*1024,"Account response is too large");bytes.extend_from_slice(&chunk);}let value:Value=serde_json::from_slice(&bytes).map_err(|_|failure(503,"service_unavailable","The account service is unavailable. Please try again later."))?;if !status.is_success(){let message=value["error"].as_str().unwrap_or("The account service could not finish this request.").chars().take(240).collect::<String>();return Err(AccountError{status:status.as_u16(),code:if status.as_u16()==401{"password_required"}else{"service_error"},message}.into());}Ok(value)}
 async fn proof(&self)->Result<Value>{let challenge=self.request(reqwest::Method::POST,"/v1/challenge",Some(json!({})),None).await?;let id=challenge["id"].as_str().unwrap_or("").to_string();let bits=challenge["bits"].as_u64().unwrap_or(0) as u32;anyhow::ensure!(id.len()==48&&id.bytes().all(|b|b.is_ascii_hexdigit())&&(1..=22).contains(&bits),"Invalid account challenge");let copy=id.clone();let nonce=tokio::task::spawn_blocking(move||solve(&copy,bits)).await??;Ok(json!({"id":id,"nonce":nonce}))}
 pub async fn authenticate(&self,id:Option<&str>,name:&str,password:&str,create:bool)->Result<Candidate>{if password.is_empty()&&!create{let id=id.context("Choose a profile")?;let cached=self.registry.lock().await.profiles.get(id).cloned().context("Choose a saved profile")?;let token=cached.token.as_deref().ok_or_else(||failure(401,"password_required","Enter your password to log in."))?;if cached.expires_at<=now(){return Err(failure(401,"password_required","Enter your password to log in again."));}match self.request(reqwest::Method::GET,"/v1/session",None,Some(token)).await{Ok(value)=>{anyhow::ensure!(value["profile"]["id"]==cached.id,"Account identity changed");let mut saved=cached;saved.expires_at=value["expires_at"].as_u64().unwrap_or(saved.expires_at);return Ok(Candidate{saved,offline:false});},Err(error)=>{if error.downcast_ref::<AccountError>().is_some_and(|e|e.code=="offline"){return Ok(Candidate{saved:cached,offline:true});}if error.downcast_ref::<AccountError>().is_some_and(|e|e.status==401){let mut registry=self.registry.lock().await;if let Some(saved)=registry.profiles.get_mut(id){saved.token=None;}atomic_registry(&self.file,&registry,&self.key)?;}return Err(error);}}}
 anyhow::ensure!(name.len()>=3&&name.len()<=32&&name.bytes().all(|b|b.is_ascii_alphanumeric()||b"_.-".contains(&b)),"Use 3–32 letters, numbers, dots, underscores or hyphens for your username");anyhow::ensure!(password.chars().count()>=10&&password.len()<=512,"Use a password of at least 10 characters");let proof=self.proof().await?;let value=self.request(reqwest::Method::POST,if create{"/v1/register"}else{"/v1/login"},Some(json!({"username":name,"password":password,"proof":proof})),None).await?;let profile=&value["profile"];let remote_id=profile["id"].as_str().context("Account identity is missing")?.to_string();crate::profile_paths::profile_root(&remote_id)?;if let Some(id)=id{anyhow::ensure!(id==remote_id,"The selected profile does not match this account");}let token=value["token"].as_str().filter(|s|s.len()==64&&s.bytes().all(|b|b.is_ascii_hexdigit())).context("Invalid account session")?.to_string();let username=profile["username"].as_str().filter(|s|!s.is_empty()&&s.len()<=32).context("Invalid account username")?.to_string();Ok(Candidate{saved:Saved{id:remote_id,username,token:Some(token),expires_at:value["expires_at"].as_u64().context("Invalid session expiry")?,appearance:Value::Null,ui_migrated:false},offline:false})}
 pub async fn commit(&self,candidate:Candidate)->Result<Active>{self.required.store(true,Ordering::Release);let mut registry=self.registry.lock().await;let mut saved=candidate.saved;if let Some(previous)=registry.profiles.get(&saved.id){saved.appearance=previous.appearance.clone();saved.ui_migrated=previous.ui_migrated;}anyhow::ensure!(registry.profiles.contains_key(&saved.id)||registry.profiles.len()<50,"This computer already has 50 saved profiles. Remove a saved sign-in first.");if registry.first_profile.is_none(){let owner=self.root.join("first-profile");if owner.exists(){registry.first_profile=Some(std::fs::read_to_string(&owner)?.trim().into());}else{write_private(&owner,saved.id.as_bytes())?;registry.first_profile=Some(saved.id.clone());}}
 registry.profiles.insert(saved.id.clone(),saved.clone());atomic_registry(&self.file,&registry,&self.key)?;let first=registry.first_profile.as_deref()==Some(saved.id.as_str());drop(registry);let root=crate::profile_paths::profile_root(&saved.id)?;let destination=root.clone();tokio::task::spawn_blocking(move||migrate(&destination,first)).await??;saved.appearance=appearance(&root);let active=Active{id:saved.id.clone(),username:saved.username.clone(),epoch:hex(&random(16)?),offline:candidate.offline,migrate_ui:first&&!saved.ui_migrated,owns_legacy_data:first};let mut registry=self.registry.lock().await;registry.profiles.insert(saved.id.clone(),saved);atomic_registry(&self.file,&registry,&self.key)?;*self.active.write().unwrap_or_else(|e|e.into_inner())=Some(active.clone());*self.warning.write().unwrap_or_else(|e|e.into_inner())=None;Ok(active)}
 pub async fn acknowledge_ui(&self)->Result<()>{let active=self.active().context("Sign in first")?;let mut registry=self.registry.lock().await;if let Some(saved)=registry.profiles.get_mut(&active.id){saved.ui_migrated=true;}atomic_registry(&self.file,&registry,&self.key)}
 pub async fn cache_appearance(&self,value:Value)->Result<()>{if let Some(active)=self.active(){let mut registry=self.registry.lock().await;if let Some(saved)=registry.profiles.get_mut(&active.id){saved.appearance=value;}atomic_registry(&self.file,&registry,&self.key)?;}Ok(())}
 pub async fn remove(&self,id:&str)->Result<()>{anyhow::ensure!(self.active().is_none(),"Sign out before removing a saved profile");let saved={let mut registry=self.registry.lock().await;let saved=registry.profiles.remove(id).context("Choose a saved profile")?;atomic_registry(&self.file,&registry,&self.key)?;atomic_registry(&self.file,&registry,&self.key)?;saved};if let Some(token)=saved.token{let _=self.request(reqwest::Method::DELETE,"/v1/session",None,Some(&token)).await;}Ok(())}
 pub async fn cloud_read(&self)->Result<Value>{let active=self.active().context("Sign in first")?;let token=self.registry.lock().await.profiles.get(&active.id).and_then(|p|p.token.clone()).context("Sign in again to sync")?;self.request(reqwest::Method::GET,"/v1/sync",None,Some(&token)).await}
 pub async fn cloud_write(&self,revision:u64,document:Value)->Result<Value>{let active=self.active().context("Sign in first")?;let token=self.registry.lock().await.profiles.get(&active.id).and_then(|p|p.token.clone()).context("Sign in again to sync")?;self.request(reqwest::Method::PUT,"/v1/sync",Some(json!({"revision":revision,"document":document})),Some(&token)).await}
}
fn solve(id:&str,bits:u32)->Result<u32>{let prefix=format!("{id}:");let mut context=ring::digest::Context::new(&ring::digest::SHA256);context.update(prefix.as_bytes());let started=std::time::Instant::now();for nonce in 0..(1u32<<26){let mut digest=context.clone();digest.update(nonce.to_string().as_bytes());let digest=digest.finish();let full=(bits/8) as usize;let partial=bits%8;if digest.as_ref()[..full].iter().all(|b|*b==0)&&(partial==0||digest.as_ref()[full]>>(8-partial)==0){return Ok(nonce);}if nonce%4096==0&&started.elapsed()>Duration::from_secs(12){break;}}anyhow::bail!("Preparing secure sign-in took too long. Please try again.")}

#[cfg(test)]mod tests{
 use super::*;
 #[test]fn tokens_are_encrypted_authenticated_and_key_bound(){let registry=Registry{profiles:BTreeMap::from([("12345678-1234-1234-1234-123456789abc".into(),Saved{id:"12345678-1234-1234-1234-123456789abc".into(),username:"UniquePrivateProfileName".into(),token:Some("a".repeat(64)),expires_at:1,appearance:Value::Null,ui_migrated:false})]),first_profile:None};let bytes=seal(&registry,&[7;32]).unwrap();let text=String::from_utf8(bytes.clone()).unwrap();assert!(!text.contains("UniquePrivateProfileName"));assert!(!text.contains(&"a".repeat(64)));assert_eq!(open(&bytes,&[7;32]).unwrap().profiles.len(),1);assert!(open(&bytes,&[8;32]).is_err());let mut modified:Value=serde_json::from_slice(&bytes).unwrap();modified["nonce"]=json!("0".repeat(24));assert!(open(&serde_json::to_vec(&modified).unwrap(),&[7;32]).is_err());}
 #[test]fn proof_uses_the_server_protocol(){let id="0".repeat(48);let nonce=solve(&id,8).unwrap();assert_eq!(ring::digest::digest(&ring::digest::SHA256,format!("{id}:{nonce}").as_bytes()).as_ref()[0],0);}
 #[test]fn registry_recovers_the_last_complete_backup(){let dir=std::env::temp_dir().join(format!("plazcode-profile-crypto-{}",hex(&random(6).unwrap())));private_dir(&dir).unwrap();let path=dir.join("accounts.v1.json");let registry=Registry::default();atomic_registry(&path,&registry,&[4;32]).unwrap();atomic_registry(&path,&registry,&[4;32]).unwrap();std::fs::write(&path,b"broken").unwrap();assert!(read_registry(&path,&[4;32]).is_ok());assert!(read_registry(&path,&[5;32]).is_err());std::fs::remove_dir_all(dir).unwrap();}
}

#[cfg(test)]mod migration_tests{use super::*;
 #[test]fn legacy_data_moves_only_to_first_identity_and_originals_survive(){let dir=std::env::temp_dir().join(format!("plazcode-migration-{}",hex(&random(8).unwrap())));let legacy=dir.join("legacy");private_dir(&legacy).unwrap();std::fs::write(legacy.join("memory.json"),b"private memory").unwrap();std::fs::write(legacy.join("not-profile-data"),b"secret device key").unwrap();let settings=dir.join("old-settings.json");std::fs::write(&settings,b"old settings").unwrap();let first=dir.join("profiles/first");migrate_from(&first,true,&legacy,&settings).unwrap();assert_eq!(std::fs::read(first.join("memory.json")).unwrap(),b"private memory");assert_eq!(std::fs::read(legacy.join("memory.json")).unwrap(),b"private memory");assert!(!first.join("not-profile-data").exists());std::fs::write(first.join("memory.json"),b"new profile edits").unwrap();migrate_from(&first,true,&legacy,&settings).unwrap();assert_eq!(std::fs::read(first.join("memory.json")).unwrap(),b"new profile edits");let second=dir.join("profiles/second");migrate_from(&second,false,&legacy,&settings).unwrap();assert!(!second.join("memory.json").exists());assert!(!second.join("plazcode-settings.json").exists());std::fs::remove_dir_all(dir).unwrap();}
 #[cfg(unix)]#[test]fn migration_rejects_symlinks_and_keeps_originals(){use std::os::unix::fs::symlink;let dir=std::env::temp_dir().join(format!("plazcode-migration-link-{}",hex(&random(8).unwrap())));private_dir(&dir).unwrap();let legacy=dir.join("legacy");private_dir(&legacy).unwrap();let original=dir.join("original");std::fs::write(&original,b"private").unwrap();symlink(&original,legacy.join("memory.json")).unwrap();assert!(migrate_from(&dir.join("profiles/new"),true,&legacy,&dir.join("none")).is_err());assert_eq!(std::fs::read(original).unwrap(),b"private");assert!(!dir.join("profiles/new/.profile-ready").exists());std::fs::remove_dir_all(dir).unwrap();}
}
